function drawVulpixAlolanIceFox(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.2;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 3.0;

  const tailLag = breathPhase - 0.45;
  const tailSwayX = Math.sin(tailLag) * 6.0;
  const tailSwayY = Math.cos(tailLag) * 3.0;

  // Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 26 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // Đuôi mây tuyết
  const tx = 18 + tailSwayX;
  const ty = by - 2 + tailSwayY;
  ctx.fillStyle = '#bae6fd';
  ctx.beginPath(); ctx.arc(tx + 4, ty - 8, 9, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.arc(tx + 8, ty, 10, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(tx + 2, ty + 10, 8, 0, Math.PI * 2); ctx.fill();

  // Thân & chân
  ctx.beginPath(); ctx.ellipse(0, by + 14, 14 * sX, 12 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#bae6fd';
  ctx.beginPath(); ctx.roundRect(-14, by + 24, 6, 12, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(-6,  by + 24, 6, 12, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(2,   by + 24, 6, 12, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(10,  by + 24, 6, 12, 3); ctx.fill();

  // Đầu
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.ellipse(0, by - 10, 18 * sX, 14 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // Tai
  ctx.beginPath(); ctx.moveTo(-14, by - 18); ctx.lineTo(-24, by - 38); ctx.lineTo(-4, by - 22); ctx.fill();
  ctx.beginPath(); ctx.moveTo(4,   by - 22); ctx.lineTo(24,  by - 38); ctx.lineTo(14, by - 18); ctx.fill();
  ctx.fillStyle = '#0284c7';
  ctx.beginPath(); ctx.moveTo(-15, by - 20); ctx.lineTo(-22, by - 34); ctx.lineTo(-7, by - 24); ctx.fill();
  ctx.beginPath(); ctx.moveTo(7,   by - 24); ctx.lineTo(22,  by - 34); ctx.lineTo(15, by - 20); ctx.fill();

  // Chỏm tóc mây
  ctx.fillStyle = '#ffffff';
  ctx.beginPath(); ctx.arc(0, by - 21, 7, 0, Math.PI * 2); ctx.fill();

  // Mắt
  if (!blink) {
    ctx.fillStyle = '#0284c7';
    ctx.beginPath(); ctx.ellipse(-8, by - 10, 4, 7, 0, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(8,  by - 10, 4, 7, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-9, by - 13, 2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(7,  by - 13, 2, 0, Math.PI * 2); ctx.fill();
  }

  // Mũi & miệng
  ctx.strokeStyle = '#0284c7';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(-2, by - 2); ctx.lineTo(2, by - 2);
  ctx.stroke();

  ctx.restore();
}
